import{_ as t,o as c,c as a,a0 as s}from"./chunks/framework.DCluYYrN.js";const g=JSON.parse('{"title":"Hướng dẫn mô-đun","description":"","frontmatter":{},"headers":[],"relativePath":"vi_VN/guide/module.md","filePath":"vi_VN/guide/module.md"}'),e={name:"vi_VN/guide/module.md"};function i(h,n,o,l,p,d){return c(),a("div",null,[...n[0]||(n[0]=[s(`<h1 id="huong-dan-mo-đun" tabindex="-1">Hướng dẫn mô-đun <a class="header-anchor" href="#huong-dan-mo-đun" aria-label="Permalink to &quot;Hướng dẫn mô-đun&quot;">​</a></h1><p>KernelSU cung cấp một cơ chế mô-đun giúp đạt được hiệu quả sửa đổi thư mục hệ thống trong khi vẫn duy trì tính toàn vẹn của phân vùng system. Cơ chế này thường được gọi là &quot;systemless&quot;.</p><p>Cơ chế mô-đun của KernelSU gần giống với Magisk. Nếu bạn đã quen với việc phát triển mô-đun Magisk thì việc phát triển các mô-đun KernelSU cũng rất tương tự. Bạn có thể bỏ qua phần giới thiệu các mô-đun bên dưới và chỉ cần đọc <a href="./difference-with-magisk.html">difference-with-magisk</a>.</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE CHỈ CẦN THIẾT ĐỂ SỬA ĐỔI TỆP HỆ THỐNG</p><p>KernelSU sử dụng kiến trúc <a href="./metamodule.html">metamodule</a> để mount thư mục <code>system</code>. <strong>Chỉ khi module của bạn cần sửa đổi tệp <code>/system</code></strong> (thông qua thư mục <code>system</code>), bạn mới cần cài đặt metamodule (như <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>). Các tính năng module khác như scripts, quy tắc sepolicy và system.prop hoạt động mà không cần metamodule.</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>KernelSU modules support displaying interfaces and interacting with users. Xem <a href="./module-webui.html">tài liệu WebUI</a> để biết thêm chi tiết.</p><h2 id="cau-hinh-module" tabindex="-1">Cấu hình module <a class="header-anchor" href="#cau-hinh-module" aria-label="Permalink to &quot;Cấu hình module&quot;">​</a></h2><p>KernelSU cung cấp hệ thống cấu hình tích hợp cho phép các module lưu trữ các cài đặt key-value liên tục hoặc tạm thời. Để biết thêm chi tiết, xem <a href="./module-config.html">tài liệu Cấu hình module</a>.</p><h2 id="script-chay-mot-lan" tabindex="-1">Script chạy một lần <a class="header-anchor" href="#script-chay-mot-lan" aria-label="Permalink to &quot;Script chạy một lần&quot;">​</a></h2><p>ZIP module cũng có thể là script chạy một lần, được trình quản lý KernelSU chạy một lần thay vì cài đặt. Để biết thêm chi tiết, xem <a href="./module-script.html">tài liệu Script chạy một lần</a>.</p><h2 id="busybox" tabindex="-1">Busybox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;Busybox&quot;">​</a></h2><p>KernelSU cung cấp tính năng nhị phân BusyBox hoàn chỉnh (bao gồm hỗ trợ SELinux đầy đủ). Tệp thực thi được đặt tại <code>/data/adb/ksu/bin/busybox</code>. BusyBox của KernelSU hỗ trợ &quot;ASH Standalone Shell Mode&quot; có thể chuyển đổi thời gian chạy. Standalone mode này có nghĩa là khi chạy trong shell <code>ash</code> của BusyBox, mọi lệnh sẽ trực tiếp sử dụng applet trong BusyBox, bất kể cái gì được đặt là <code>PATH</code>. Ví dụ: các lệnh như <code>ls</code>, <code>rm</code>, <code>chmod</code> sẽ <strong>KHÔNG</strong> sử dụng những gì có trong <code>PATH</code> (trong trường hợp Android theo mặc định, nó sẽ là <code>/system/bin/ls</code>, <code> /system/bin/rm</code> và <code>/system/bin/chmod</code> tương ứng), nhưng thay vào đó sẽ gọi trực tiếp các ứng dụng BusyBox nội bộ. Điều này đảm bảo rằng các tập lệnh luôn chạy trong môi trường có thể dự đoán được và luôn có bộ lệnh đầy đủ cho dù nó đang chạy trên phiên bản Android nào. Để buộc lệnh <em>not</em> sử dụng BusyBox, bạn phải gọi tệp thực thi có đường dẫn đầy đủ.</p><p>Mỗi tập lệnh shell đơn lẻ chạy trong ngữ cảnh của KernelSU sẽ được thực thi trong shell <code>ash</code> của BusyBox với standalone mode được bật. Đối với những gì liên quan đến nhà phát triển bên thứ 3, điều này bao gồm tất cả các tập lệnh khởi động và tập lệnh cài đặt mô-đun.</p><p>Đối với những người muốn sử dụng tính năng &quot;Standalone mode&quot; này bên ngoài KernelSU, có 2 cách để kích hoạt tính năng này:</p><ol><li>Đặt biến môi trường <code>ASH_STANDALONE</code> thành <code>1</code><br>Ví dụ: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>Chuyển đổi bằng các tùy chọn dòng lệnh:<br><code>/data/adb/ksu/bin/busybox sh -o độc lập &lt;script&gt;</code></li></ol><p>Để đảm bảo tất cả shell <code>sh</code> tiếp theo được thực thi cũng chạy ở standalone mode, tùy chọn 1 là phương thức ưu tiên (và đây là những gì KernelSU và KernelSU manager sử dụng nội bộ) vì các biến môi trường được kế thừa xuống các tiến trình con.</p><div class="tip custom-block"><p class="custom-block-title">sự khác biệt với Magisk</p><p>BusyBox của KernelSU hiện đang sử dụng tệp nhị phân được biên dịch trực tiếp từ dự án Magisk. <strong>Cảm ơn Magisk!</strong> Vì vậy, bạn không phải lo lắng về vấn đề tương thích giữa các tập lệnh BusyBox trong Magisk và KernelSU vì chúng hoàn toàn giống nhau!</p></div><h2 id="mo-đun-hat-nhansu" tabindex="-1">Mô-đun hạt nhânSU <a class="header-anchor" href="#mo-đun-hat-nhansu" aria-label="Permalink to &quot;Mô-đun hạt nhânSU&quot;">​</a></h2><p>Mô-đun KernelSU là một thư mục được đặt trong <code>/data/adb/modules</code> với cấu trúc bên dưới:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- Thư mục được đặt tên bằng ID của mô-đun</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Nhận Dạng Mô-đun ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- Tệp này lưu trữ metadata của mô-đun</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Nội Dung Chính ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- Thư mục này sẽ được gắn kết nếu skip_mount không tồn tại</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Cờ Trạng Thái ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- Nếu tồn tại, KernelSU sẽ KHÔNG gắn kết thư mục hệ thống của bạn</span></span>
<span class="line"><span>│   ├── disable             &lt;--- Nếu tồn tại, mô-đun sẽ bị vô hiệu hóa</span></span>
<span class="line"><span>│   ├── remove              &lt;--- Nếu tồn tại, mô-đun sẽ bị xóa trong lần khởi động lại tiếp theo</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Tệp Tùy Chọn ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- Tập lệnh này sẽ được thực thi trong post-fs-data</span></span>
<span class="line"><span>│   ├── post-mount.sh       &lt;--- Tập lệnh này sẽ được thực thi trong post-mount</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- Tập lệnh này sẽ được thực thi trong dịch vụ late_start</span></span>
<span class="line"><span>│   ├── boot-completed.sh   &lt;--- Tập lệnh này sẽ được thực thi khi khởi động xong</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- Tập lệnh này sẽ được thực thi khi KernelSU xóa mô-đun của bạn</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- Các thuộc tính trong tệp này sẽ được tải dưới dạng thuộc tính hệ thống bằng resetprop</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- Quy tắc riêng biệt tùy chỉnh bổ sung</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- Các tệp .rc trong thư mục này sẽ được chèn vào init.rc khi khởi động</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Được Tạo Tự Động, KHÔNG TẠO HOẶC SỬA ĐỔI THỦ CÔNG ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- Một liên kết tượng trưng đến $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- Một liên kết tượng trưng đến $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- Một liên kết tượng trưng đến $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Mọi tập tin / thư mục bổ sung đều được phép ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">sự khác biệt với Magisk</p><p>KernelSU không có hỗ trợ tích hợp cho Zygisk nên không có nội dung liên quan đến Zygisk trong mô-đun. Tuy nhiên, bạn có thể sử dụng <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> để hỗ trợ các mô-đun Zygisk. Trong trường hợp này, nội dung của mô-đun Zygisk giống hệt với nội dung được Magisk hỗ trợ.</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p>module.prop là tệp cấu hình cho mô-đun. Trong KernelSU, nếu một mô-đun không chứa tệp này, nó sẽ không được nhận dạng là mô-đun. Định dạng của tập tin này như sau:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (optional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (optional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (optional)</span></span></code></pre></div><ul><li><code>id</code> phải khớp với biểu thức chính quy này: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> ví dụ: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> Đây là <strong>mã định danh duy nhất</strong> của mô-đun của bạn. Bạn không nên thay đổi nó sau khi được xuất bản.</li><li><code>versionCode</code> phải là <strong>số nguyên</strong>. Điều này được sử dụng để so sánh các phiên bản.</li><li>Các chuỗi khác không được đề cập ở trên có thể là chuỗi <strong>một dòng</strong> bất kỳ.</li><li>Đảm bảo sử dụng kiểu ngắt dòng <code>UNIX (LF)</code> chứ không phải <code>Windows (CR+LF)</code> hoặc <code>Macintosh (CR)</code>.</li><li><code>actionIcon</code> và <code>webuiIcon</code> là các đường dẫn hình ảnh tùy chọn, được dùng làm biểu tượng mặc định cho phím tắt hành động và phím tắt WebUI của mô-đun trong ứng dụng quản lý. Các đường dẫn này phải là đường dẫn tương đối so với thư mục gốc của mô-đun. Ví dụ, <code>actionIcon=icon/icon.png</code> sẽ được ánh xạ thành <code>&lt;MODDIR&gt;/icon/icon.png</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">MÔ TẢ ĐỘNG</p><p>Trường <code>description</code> có thể được ghi đè động khi chạy bằng hệ thống cấu hình mô-đun. Xem <a href="./module-config.html#overriding-module-description">Ghi đè Mô tả Mô-đun</a> để biết chi tiết.</p></div><h3 id="tap-lenh-shell" tabindex="-1">Tập lệnh Shell <a class="header-anchor" href="#tap-lenh-shell" aria-label="Permalink to &quot;Tập lệnh Shell&quot;">​</a></h3><p>Vui lòng đọc phần <a href="#boot-scripts">Boot Scripts</a> để hiểu sự khác biệt giữa <code>post-fs-data.sh</code> và <code>service.sh</code>. Đối với hầu hết các nhà phát triển mô-đun, <code>service.sh</code> sẽ đủ tốt nếu bạn chỉ cần chạy tập lệnh khởi động, nếu bạn cần chạy tập lệnh sau khi khởi động xong, vui lòng sử dụng <code>boot-completed.sh</code>. Nếu bạn muốn làm gì đó sau khi gắn các lớp phủ, vui lòng sử dụng <code>post-mount.sh</code>.</p><p>Trong tất cả các tập lệnh của mô-đun của bạn, vui lòng sử dụng <code>MODDIR=\${0%/*}</code> để lấy đường dẫn thư mục cơ sở của mô-đun của bạn; <strong>KHÔNG</strong> mã hóa cứng đường dẫn mô-đun của bạn trong tập lệnh.</p><div class="tip custom-block"><p class="custom-block-title">sự khác biệt với Magisk</p><p>Bạn có thể sử dụng biến môi trường KSU để xác định xem tập lệnh đang chạy trong KernelSU hay Magisk. Nếu chạy trong KernelSU, giá trị này sẽ được đặt thành true.</p></div><h3 id="thu-muc-system" tabindex="-1">thư mục <code>system</code> <a class="header-anchor" href="#thu-muc-system" aria-label="Permalink to &quot;thư mục \`system\`&quot;">​</a></h3><p>Nội dung của thư mục này sẽ được phủ lên trên phân vùng /system của hệ thống sau khi hệ thống được khởi động. Điều này có nghĩa rằng:</p><div class="tip custom-block"><p class="custom-block-title">YÊU CẦU METAMODULE</p><p>Thư mục <code>system</code> chỉ được mount nếu bạn đã cài đặt metamodule cung cấp chức năng mounting (như <code>meta-overlayfs</code>). Metamodule xử lý cách các module được mount. Xem <a href="./metamodule.html">Hướng dẫn Metamodule</a> để biết thêm thông tin.</p></div><ol><li>Các file có cùng tên với các file trong thư mục tương ứng trong hệ thống sẽ bị ghi đè bởi các file trong thư mục này.</li><li>Các thư mục có cùng tên với thư mục tương ứng trong hệ thống sẽ được gộp với các thư mục trong thư mục này.</li></ol><p>Nếu bạn muốn xóa một tập tin hoặc thư mục trong thư mục hệ thống gốc, bạn cần tạo một tập tin có cùng tên với tập tin/thư mục trong thư mục mô-đun bằng cách sử dụng <code>mknod filename c 0 0</code>. Bằng cách này, hệ thống lớp phủ sẽ tự động &quot;whiteout&quot; (Xóa trắng) tệp này như thể nó đã bị xóa (phân vùng /system không thực sự bị thay đổi).</p><p>Bạn cũng có thể khai báo một biến có tên <code>REMOVE</code> chứa danh sách các thư mục trong <code>customize.sh</code> để thực hiện các thao tác xóa và KernelSU sẽ tự động thực thi <code>mknod &lt;TARGET&gt; c 0 0</code> trong các thư mục tương ứng của mô-đun. Ví dụ:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Danh sách trên sẽ thực thi <code>mknod $MODPATH/system/app/YouTuBe c 0 0</code> và <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>; và <code>/system/app/YouTube</code> và <code>/system/app/Bloatware</code> sẽ bị xóa sau khi mô-đun này có hiệu lực.</p><p>Nếu bạn muốn thay thế một thư mục trong hệ thống, bạn cần tạo một thư mục có cùng đường dẫn trong thư mục mô-đun của mình, sau đó đặt thuộc tính <code>setfattr -ntrust.overlay.opaque -v y &lt;TARGET&gt;</code> cho thư mục này. Bằng cách này, hệ thống Overlayfs sẽ tự động thay thế thư mục tương ứng trong hệ thống (mà không thay đổi phân vùng /system).</p><p>Bạn có thể khai báo một biến có tên <code>REPLACE</code> trong tệp <code>customize.sh</code> của mình, bao gồm danh sách các thư mục sẽ được thay thế và KernelSU sẽ tự động thực hiện các thao tác tương ứng trong thư mục mô-đun của bạn. Ví dụ:</p><p>REPLACE=&quot; /system/app/YouTube /system/app/Bloatware &quot;</p><p>Danh sách này sẽ tự động tạo các thư mục <code>$MODPATH/system/app/YouTube</code> và <code>$MODPATH/system/app/Bloatware</code>, sau đó thực thi <code>setfattr -ntrusted.overlay.opaque -v y $MODPATH/system/app/ YouTube</code> và <code>setfattr -n Trust.overlay.opaque -v y $MODPATH/system/app/Bloatware</code>. Sau khi mô-đun có hiệu lực, <code>/system/app/YouTube</code> và <code>/system/app/Bloatware</code> sẽ được thay thế bằng các thư mục trống.</p><div class="tip custom-block"><p class="custom-block-title">sự khác biệt với Magisk</p><p>KernelSU sử dụng kiến trúc <a href="./metamodule.html">metamodule</a> trong đó việc mounting được ủy thác cho các metamodule có thể cắm được. Metamodule <code>meta-overlayfs</code> chính thức sử dụng OverlayFS của kernel cho các sửa đổi systemless, trong khi Magisk sử dụng magic mount (bind mount) được tích hợp trực tiếp vào lõi của nó. Cả hai đều đạt được cùng một mục tiêu: sửa đổi tệp <code>/system</code> mà không sửa đổi vật lý phân vùng <code>/system</code>. Cách tiếp cận của KernelSU mang lại tính linh hoạt cao hơn và giảm bề mặt phát hiện.</p></div><p>Nếu bạn quan tâm đến overlayfs, bạn nên đọc <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">documentation on overlayfs</a> của Kernel Linux.</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>Tệp này có cùng định dạng với <code>build.prop</code>. Mỗi dòng bao gồm <code>[key]=[value]</code>.</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>Nếu mô-đun của bạn yêu cầu một số bản vá lỗi chính sách bổ sung, vui lòng thêm các quy tắc đó vào tệp này. Mỗi dòng trong tệp này sẽ được coi là một tuyên bố chính sách.</p><h3 id="initrc-injection" tabindex="-1">Chèn initrc (initrc Injection) <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;Chèn initrc (initrc Injection) {#initrc-injection}&quot;">​</a></h3><p>KernelSU cung cấp cơ chế chèn các chỉ thị Android Init RC tùy chỉnh vào <code>init.rc</code> của hệ thống. Điều này cho phép các mô-đun đăng ký các dịch vụ Android tùy chỉnh, thiết lập trình kích hoạt thuộc tính hoặc thực hiện các hành động ngôn ngữ Init khác mà không cần sửa đổi phân vùng hệ thống.</p><p>Trong quá trình khởi động, mô-đun hạt nhân KernelSU chặn các lệnh gọi hệ thống <code>read()</code> và <code>fstat()</code>. Khi quá trình init của Android đọc <code>/system/etc/init/hw/init.rc</code>, KernelSU sẽ thêm nội dung RC tùy chỉnh vào cuối tệp một cách minh bạch. Quá trình init phân tích các chỉ thị được chèn này giống như nội dung init.rc gốc.</p><p>Ở phía không gian người dùng, ksud nối tất cả các tệp <code>.rc</code> từ các mô-đun đã bật thành một tệp <code>modules.rc</code> duy nhất, được lưu trữ trên phân vùng <code>/metadata</code>. Tệp này tự động được tạo lại bất cứ khi nào trạng thái của mô-đun thay đổi (cài đặt, bật, tắt, gỡ cài đặt, v.v.).</p><h4 id="tep-initrc-cua-mo-đun" tabindex="-1">Tệp initrc của mô-đun <a class="header-anchor" href="#tep-initrc-cua-mo-đun" aria-label="Permalink to &quot;Tệp initrc của mô-đun&quot;">​</a></h4><p>Tạo một thư mục con <code>initrc/</code> trong thư mục mô-đun của bạn và đặt các tệp <code>.rc</code> của bạn vào đó:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Các tệp phải có đuôi mở rộng là <code>.rc</code>.</li><li>Miễn là mô-đun được bật, tất cả các tệp <code>.rc</code> trong thư mục <code>initrc/</code> sẽ được bao gồm (không cần quyền thực thi).</li><li>Các tệp được xử lý theo <strong>thứ tự bảng chữ cái của tên tệp</strong> trong thư mục và các mô-đun được xử lý theo <strong>thứ tự bảng chữ cái của ID mô-đun</strong>.</li></ul></div><h4 id="tep-initrc-chung" tabindex="-1">Tệp initrc chung <a class="header-anchor" href="#tep-initrc-chung" aria-label="Permalink to &quot;Tệp initrc chung&quot;">​</a></h4><p>Ngoài các tệp RC ở cấp mô-đun, bạn có thể đặt các tệp <code>.rc</code> trong thư mục toàn cầu:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Các tệp initrc chung yêu cầu quyền thực thi</p><p>Khác với thư mục <code>initrc/</code> của mô-đun, các tệp trong <code>/data/adb/initrc.d/</code> <strong>phải có quyền thực thi</strong> để được bao gồm. Các tệp <code>.rc</code> không thực thi được sẽ bị bỏ qua một cách âm thầm.</p></div><p>Các tệp <code>initrc.d/</code> chung được xử lý trước bất kỳ tệp RC mô-đun nào.</p><h4 id="vi-du" tabindex="-1">Ví dụ <a class="header-anchor" href="#vi-du" aria-label="Permalink to &quot;Ví dụ&quot;">​</a></h4><p>Dưới đây là ví dụ về tệp <code>.rc</code> đăng ký một dịch vụ Android tùy chỉnh:</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>Nếu tệp này được đặt tại <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>, nó sẽ đăng ký một dịch vụ có tên là <code>myservice</code> khi khởi động và bắt đầu nó khi đạt đến <code>sys.boot_completed=1</code>.</p><h4 id="lam-moi-thu-cong" tabindex="-1">Làm mới thủ công <a class="header-anchor" href="#lam-moi-thu-cong" aria-label="Permalink to &quot;Làm mới thủ công&quot;">​</a></h4><p>Bạn có thể kích hoạt thủ công việc tạo lại <code>modules.rc</code> bằng lệnh sau (các thay đổi sẽ có hiệu lực trong lần khởi động tiếp theo):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Việc chèn initrc xảy ra rất sớm trong quá trình khởi động (khi init đọc init.rc), <strong>trước</strong> post-fs-data và bất kỳ tập lệnh mô-đun nào được thực thi.</li><li>Nội dung RC được chèn được init coi là một phần của init.rc gốc, hỗ trợ tất cả cú pháp ngôn ngữ Android Init (định nghĩa dịch vụ, trình kích hoạt, cài đặt thuộc tính, v.v.).</li><li>Chèn initrc <strong>không khả dụng</strong> trong <strong>chế độ late-load</strong>, vì các móc gọi hệ thống không được cài đặt trong chế độ đó.</li><li>Có thể tắt chèn RC mô-đun bằng cách truyền tham số <code>--no-custom-rc</code> khi vá hình ảnh bằng ksud.</li></ul></div><h2 id="trinh-cai-đat-mo-đun" tabindex="-1">Trình cài đặt mô-đun <a class="header-anchor" href="#trinh-cai-đat-mo-đun" aria-label="Permalink to &quot;Trình cài đặt mô-đun&quot;">​</a></h2><p>Trình cài đặt mô-đun KernelSU là mô-đun KernelSU được đóng gói trong tệp zip có thể được flash trong APP KernelSU manager. Trình cài đặt mô-đun KernelSU đơn giản chỉ là mô-đun KernelSU được đóng gói dưới dạng tệp zip.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Tùy chọn, biết thêm chi tiết sau)</span></span>
<span class="line"><span>│                                           Tập lệnh này sẽ có nguồn gốc từ update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* Các tập tin còn lại của mô-đun */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Mô-đun KernelSU KHÔNG được hỗ trợ để cài đặt trong khôi phục tùy chỉnh!!</p></div><h3 id="tuy-chinh" tabindex="-1">Tùy chỉnh <a class="header-anchor" href="#tuy-chinh" aria-label="Permalink to &quot;Tùy chỉnh&quot;">​</a></h3><p>Nếu bạn cần tùy chỉnh quá trình cài đặt mô-đun, bạn có thể tùy ý tạo một tập lệnh trong trình cài đặt có tên <code>customize.sh</code>. Tập lệnh này sẽ được <em>sourced</em> (không được thực thi!) bởi tập lệnh cài đặt mô-đun sau khi tất cả các tệp được trích xuất và các quyền mặc định cũng như văn bản thứ hai được áp dụng. Điều này rất hữu ích nếu mô-đun của bạn yêu cầu thiết lập bổ sung dựa trên ABI của thiết bị hoặc bạn cần đặt các quyền/văn bản thứ hai đặc biệt cho một số tệp mô-đun của mình.</p><p>Nếu bạn muốn kiểm soát và tùy chỉnh hoàn toàn quá trình cài đặt, hãy khai báo <code>SKIPUNZIP=1</code> trong <code>customize.sh</code> để bỏ qua tất cả các bước cài đặt mặc định. Bằng cách đó, <code>customize.sh</code> của bạn sẽ chịu trách nhiệm cài đặt mọi thứ.</p><p>Tập lệnh <code>customize.sh</code> chạy trong shell <code>ash</code> BusyBox của KernelSU với &quot;Chế độ độc lập&quot; được bật. Có sẵn các biến và hàm sau:</p><h4 id="bien" tabindex="-1">Biến <a class="header-anchor" href="#bien" aria-label="Permalink to &quot;Biến&quot;">​</a></h4><ul><li><code>KSU</code> (bool): biến để đánh dấu script đang chạy trong môi trường KernelSU, và giá trị của biến này sẽ luôn đúng. Bạn có thể sử dụng nó để phân biệt giữa KernelSU và Magisk.</li><li><code>KSU_VER</code> (chuỗi): chuỗi phiên bản của KernelSU được cài đặt hiện tại (ví dụ: <code>v0.4.0</code>)</li><li><code>KSU_VER_CODE</code> (int): mã phiên bản của KernelSU được cài đặt hiện tại trong không gian người dùng (ví dụ: <code>10672</code>)</li><li><code>KSU_KERNEL_VER_CODE</code> (int): mã phiên bản của KernelSU được cài đặt hiện tại trong không gian kernel (ví dụ: <code>10672</code>)</li><li><code>BOOTMODE</code> (bool): luôn là <code>true</code> trong KernelSU</li><li><code>MODPATH</code> (đường dẫn): đường dẫn nơi các tập tin mô-đun của bạn sẽ được cài đặt</li><li><code>TMPDIR</code> (đường dẫn): nơi bạn có thể lưu trữ tạm thời các tập tin</li><li><code>ZIPFILE</code> (đường dẫn): zip cài đặt mô-đun của bạn</li><li><code>ARCH</code> (chuỗi): kiến trúc CPU của thiết bị. Giá trị là <code>arm</code>, <code>arm64</code>, <code>x86</code> hoặc <code>x64</code></li><li><code>IS64BIT</code> (bool): <code>true</code> nếu <code>$ARCH</code> là <code>arm64</code> hoặc <code>x64</code></li><li><code>API</code> (int): cấp độ API (phiên bản Android) của thiết bị (ví dụ: <code>23</code> cho Android 6.0)</li><li><code>KSU_UAPI_VER</code> (int): phiên bản UAPI của không gian người dùng KernelSU (ksud) (ví dụ: <code>2</code>). Phiên bản này được tăng lên khi có thay đổi phá vỡ tương thích trong driver kernel, và có thể được module sử dụng để kiểm tra tính tương thích.</li><li><code>KSU_RUNTIME_MODE</code> (string): chế độ chạy hiện tại của KernelSU. Các giá trị có thể là <code>built-in</code> (chế độ GKI, được biên dịch vào kernel), <code>lkm</code> (được tải dưới dạng mô-đun kernel khi khởi động), hoặc <code>late-load</code> (được tải dưới dạng mô-đun kernel sau khi khởi động).</li><li><code>KSU_LATE_LOAD</code> (int?): nếu KernelSU được tải muộn sau khi khởi động, biến này được đặt thành <code>1</code>; nếu không, biến này không được đặt.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Trong KernelSU, MAGISK_VER_CODE luôn là 25200 và MAGISK_VER luôn là v25.2. Vui lòng không sử dụng hai biến này để xác định xem nó có chạy trên KernelSU hay không.</p></div><h4 id="ham" tabindex="-1">Hàm <a class="header-anchor" href="#ham" aria-label="Permalink to &quot;Hàm&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    in &lt;msg&gt; ra console</span></span>
<span class="line"><span>    Tránh sử dụng &#39;echo&#39; vì nó sẽ không hiển thị trong console của recovery tùy chỉnh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    in thông báo lỗi &lt;msg&gt; ra bàn điều khiển và chấm dứt cài đặt</span></span>
<span class="line"><span>    Tránh sử dụng &#39;exit&#39; vì nó sẽ bỏ qua các bước dọn dẹp chấm dứt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    nếu [context] không được đặt, mặc định là &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    chức năng này là một shorthand cho các lệnh sau:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    nếu [context] không được đặt, mặc định là &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    đối với tất cả các tệp trong &lt;directory&gt;, nó sẽ gọi:</span></span>
<span class="line"><span>       bối cảnh cấp phép tệp của nhóm chủ sở hữu tệp set_perm</span></span>
<span class="line"><span>    đối với tất cả các thư mục trong &lt;directory&gt; (bao gồm cả chính nó), nó sẽ gọi:</span></span>
<span class="line"><span>       set_perm bối cảnh phân quyền của nhóm chủ sở hữu thư mục</span></span></code></pre></div><h2 id="tap-lenh-khoi-đong" tabindex="-1">Tập lệnh khởi động <a class="header-anchor" href="#tap-lenh-khoi-đong" aria-label="Permalink to &quot;Tập lệnh khởi động&quot;">​</a></h2><p>Trong KernelSU, tập lệnh được chia thành hai loại dựa trên chế độ chạy của chúng: chế độ post-fs-data và chế độ dịch vụ late_start:</p><ul><li>chế độ post-fs-data <ul><li>Giai đoạn này là BLOCKING. Quá trình khởi động bị tạm dừng trước khi thực thi xong hoặc đã trôi qua 10 giây.</li><li>Các tập lệnh chạy trước khi bất kỳ mô-đun nào được gắn kết. Điều này cho phép nhà phát triển mô-đun tự động điều chỉnh các mô-đun của họ trước khi nó được gắn kết.</li><li>Giai đoạn này xảy ra trước khi Zygote được khởi động, điều này gần như có ý nghĩa đối với mọi thứ trong Android</li><li><strong>CẢNH BÁO:</strong> sử dụng <code>setprop</code> sẽ làm quá trình khởi động bị nghẽn! Thay vào đó, vui lòng sử dụng <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code>.</li><li><strong>Chỉ chạy tập lệnh ở chế độ này nếu cần thiết.</strong></li></ul></li><li>chế độ dịch vụ late_start <ul><li>Giai đoạn này là NON-BLOCKING. Tập lệnh của bạn chạy song song với phần còn lại của quá trình khởi động.</li><li><strong>Đây là giai đoạn được khuyến nghị để chạy hầu hết các tập lệnh.</strong></li></ul></li></ul><p>Trong KernelSU, tập lệnh khởi động được chia thành hai loại dựa trên vị trí lưu trữ của chúng: tập lệnh chung và tập lệnh mô-đun:</p><ul><li>Kịch Bản Chung <ul><li>Được đặt trong <code>/data/adb/post-fs-data.d</code>, <code>/data/adb/service.d</code>, <code>/data/adb/post-mount.d</code> hoặc <code>/data/adb/boot- đã hoàn thành.d</code></li><li>Chỉ được thực thi nếu tập lệnh được đặt là có thể thực thi được (<code>chmod +x script.sh</code>)</li><li>Các tập lệnh trong <code>post-fs-data.d</code> chạy ở chế độ post-fs-data và các tập lệnh trong <code>service.d</code> chạy ở chế độ dịch vụ late_start.</li><li>Các mô-đun <strong>KHÔNG</strong> thêm các tập lệnh chung trong quá trình cài đặt</li></ul></li><li>Tập Lệnh Mô-đun <ul><li>Được đặt trong thư mục riêng của mô-đun</li><li>Chỉ thực hiện nếu mô-đun được kích hoạt</li><li><code>post-fs-data.sh</code> chạy ở chế độ post-fs-data, <code>service.sh</code> chạy ở chế độ dịch vụ late_start, <code>boot-completed.sh</code> chạy khi khởi động xong, <code>post-mount.sh</code> chạy trên overlayfs được gắn kết.</li></ul></li></ul><p>Tất cả các tập lệnh khởi động sẽ chạy trong shell <code>ash</code> BusyBox của KernelSU với &quot;Standalone Mode&quot; được bật.</p><h2 id="late-load-mode" tabindex="-1">Chế độ late-load <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Chế độ late-load {#late-load-mode}&quot;">​</a></h2><p>Ngoài quy trình khởi động tiêu chuẩn được mô tả ở trên, KernelSU hỗ trợ <strong>chế độ late-load</strong> cho các tình huống LKM (Loadable Kernel Module). Trong chế độ này, mô-đun kernel KernelSU được tải <strong>sau khi hệ thống đã khởi động hoàn toàn</strong>, thay vì trong quá trình init.</p><h3 id="khi-nao-late-load-xay-ra" tabindex="-1">Khi nào late-load xảy ra? <a class="header-anchor" href="#khi-nao-late-load-xay-ra" aria-label="Permalink to &quot;Khi nào late-load xảy ra?&quot;">​</a></h3><p>Late-load được kích hoạt bằng cách chạy lệnh <code>ksud late-load</code>. Lệnh này:</p><ol><li>Phát hiện phiên bản KMI hiện tại và tải <code>kernelsu.ko</code> tương ứng từ tài nguyên nhúng.</li><li>Thực hiện khởi tạo mô-đun (quy tắc SELinux, danh sách cho phép, tính năng, v.v.) thường xảy ra trong quá trình khởi động.</li></ol><p>Vì hệ thống đã chạy hoàn toàn, một số cơ chế thời gian khởi động không khả dụng hoặc không cần thiết.</p><h3 id="su-khac-biet-so-voi-khoi-đong-tieu-chuan" tabindex="-1">Sự khác biệt so với khởi động tiêu chuẩn <a class="header-anchor" href="#su-khac-biet-so-voi-khoi-đong-tieu-chuan" aria-label="Permalink to &quot;Sự khác biệt so với khởi động tiêu chuẩn&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Hành vi</th><th style="text-align:center;">Khởi động tiêu chuẩn</th><th style="text-align:center;">Chế độ late-load</th></tr></thead><tbody><tr><td>Mô-đun kernel được tải bởi init (PID 1)</td><td style="text-align:center;">Có</td><td style="text-align:center;">Không (tải sau khi khởi động)</td></tr><tr><td>Hook kprobe của ksud (execve/read/fstat/input)</td><td style="text-align:center;">Có</td><td style="text-align:center;">Bỏ qua</td></tr><tr><td>Phát hiện chế độ an toàn (phím âm lượng)</td><td style="text-align:center;">Có</td><td style="text-align:center;">Luôn tắt</td></tr><tr><td>Thu thập nhật ký khởi động (logcat/dmesg)</td><td style="text-align:center;">Có</td><td style="text-align:center;">Bỏ qua</td></tr><tr><td>Kiểm tra cùng tồn tại với Magisk</td><td style="text-align:center;">Có</td><td style="text-align:center;">Bỏ qua</td></tr><tr><td>Sự kiện <code>post-fs-data</code> báo cáo cho kernel</td><td style="text-align:center;">Có</td><td style="text-align:center;">Bỏ qua</td></tr><tr><td>Sự kiện <code>boot-completed</code> báo cáo cho kernel</td><td style="text-align:center;">Có</td><td style="text-align:center;">Đặt trực tiếp khi khởi tạo</td></tr><tr><td>Tập lệnh <code>post-fs-data.sh</code> / <code>post-fs-data.d/</code></td><td style="text-align:center;">Có</td><td style="text-align:center;">Thay thế bằng giai đoạn <code>late-load</code></td></tr><tr><td>Tải <code>system.prop</code></td><td style="text-align:center;">Có</td><td style="text-align:center;">Có</td></tr><tr><td>Gắn kết OverlayFS (metamodule)</td><td style="text-align:center;">Có</td><td style="text-align:center;">Có</td></tr><tr><td>Tập lệnh <code>post-mount.sh</code> / <code>post-mount.d/</code></td><td style="text-align:center;">Có</td><td style="text-align:center;">Có</td></tr><tr><td>Tập lệnh <code>service.sh</code> / <code>service.d/</code></td><td style="text-align:center;">Có</td><td style="text-align:center;">Có</td></tr><tr><td>Tập lệnh <code>boot-completed.sh</code> / <code>boot-completed.d/</code></td><td style="text-align:center;">Có</td><td style="text-align:center;">Có</td></tr><tr><td>Biến môi trường <code>KSU_LATE_LOAD</code></td><td style="text-align:center;">Không đặt</td><td style="text-align:center;">Đặt thành <code>1</code></td></tr><tr><td>Cờ info kernel <code>0x4</code></td><td style="text-align:center;">Không đặt</td><td style="text-align:center;">Đã đặt</td></tr></tbody></table><h3 id="thu-tu-thuc-thi-tap-lenh" tabindex="-1">Thứ tự thực thi tập lệnh <a class="header-anchor" href="#thu-tu-thuc-thi-tap-lenh" aria-label="Permalink to &quot;Thứ tự thực thi tập lệnh&quot;">​</a></h3><p>Trong chế độ late-load, thứ tự thực thi tập lệnh như sau:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. Tải kernelsu.ko (nếu chưa được tải)</span></span>
<span class="line"><span>  2. Giải nén tệp nhị phân, xử lý cập nhật mô-đun, tải quy tắc SELinux, khởi tạo tính năng</span></span>
<span class="line"><span>  3. Thực thi tập lệnh late-load.d/ và tập lệnh late-load của mô-đun (chặn)</span></span>
<span class="line"><span>  4. Tải system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. Thực thi tập lệnh mount của metamodule (OverlayFS)</span></span>
<span class="line"><span>  6. Thực thi tập lệnh post-mount.d/ và post-mount.sh của mô-đun (chặn)</span></span>
<span class="line"><span>  7. Thực thi tập lệnh service.d/ và service.sh của mô-đun (không chặn)</span></span>
<span class="line"><span>  8. Thực thi tập lệnh boot-completed.d/ và boot-completed.sh của mô-đun (không chặn)</span></span></code></pre></div><h3 id="tap-lenh-danh-rieng-cho-late-load" tabindex="-1">Tập lệnh dành riêng cho late-load <a class="header-anchor" href="#tap-lenh-danh-rieng-cho-late-load" aria-label="Permalink to &quot;Tập lệnh dành riêng cho late-load&quot;">​</a></h3><p>Mô-đun có thể cung cấp tập lệnh <code>late-load.sh</code> chỉ chạy <strong>trong chế độ late-load</strong>, thay thế cho <code>post-fs-data.sh</code>. Tập lệnh này chạy trước khi gắn kết OverlayFS, tương tự như <code>post-fs-data.sh</code> trong luồng tiêu chuẩn.</p><p>Ngoài ra, các tập lệnh chung có thể được đặt trong <code>/data/adb/late-load.d/</code> để thực thi trong giai đoạn này.</p><h3 id="phat-hien-che-đo-late-load-trong-tap-lenh" tabindex="-1">Phát hiện chế độ late-load trong tập lệnh <a class="header-anchor" href="#phat-hien-che-đo-late-load-trong-tap-lenh" aria-label="Permalink to &quot;Phát hiện chế độ late-load trong tập lệnh&quot;">​</a></h3><p>Mô-đun có thể phát hiện chế độ late-load bằng cách kiểm tra biến môi trường <code>KSU_LATE_LOAD</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Đang chạy trong chế độ late-load</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>Điều này cho phép các mô-đun điều chỉnh hành vi của mình, ví dụ bỏ qua các thao tác chỉ cần thiết trong quá trình khởi động sớm.</p>`,106)])])}const u=t(e,[["render",i]]);export{g as __pageData,u as default};
